/*
 * Test suite for {@link org.jsoup.parser.TokenQueue}.
 *
 * TokenQueue is a small character reader used by jsoup's CSS selector parser.
 * These tests exercise its public API: consuming tokens/identifiers/selectors,
 * balanced-chomp parsing, whitespace handling, sequence matching, and the
 * static CSS escape/unescape helpers.
 *
 * Originally generated by EvoSuite, then refactored for readability while
 * preserving the exact calls, arguments, and expected outcomes.
 */

package org.jsoup.parser;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.jsoup.parser.TokenQueue;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class) @EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class TokenQueue_ESTest extends TokenQueue_ESTest_scaffolding {

  // ---------------------------------------------------------------------------
  // consumeElementSelector(): reads a CSS element selector (tag-name style token)
  // ---------------------------------------------------------------------------

  @Test(timeout = 4000)
  public void consumeElementSelector_stopsAtFirstNonSelectorChar() throws Throwable {
      TokenQueue queue = new TokenQueue("8)cpsx*");

      String selector = queue.consumeElementSelector();

      // Reading stops at ')', so only the leading "8" is returned.
      assertEquals("8", selector);
  }

  @Test(timeout = 4000)
  public void consumeElementSelector_readsWholeIdentifier() throws Throwable {
      TokenQueue queue = new TokenQueue("n");

      String selector = queue.consumeElementSelector();

      assertEquals("n", selector);
  }

  // ---------------------------------------------------------------------------
  // consumeCssIdentifier(): reads/unescapes a CSS identifier (id or class)
  // ---------------------------------------------------------------------------

  @Test(timeout = 4000)
  public void consumeCssIdentifier_readsIdentifierWithUnderscoreAndDigits() throws Throwable {
      TokenQueue queue = new TokenQueue("dQ_7Q");

      String identifier = queue.consumeCssIdentifier();

      assertEquals("dQ_7Q", identifier);
  }

  @Test(timeout = 4000)
  public void consumeCssIdentifier_returnsEmptyWhenFirstCharIsNotIdentifier() throws Throwable {
      TokenQueue queue = new TokenQueue("'");

      String identifier = queue.consumeCssIdentifier();

      // A single quote is not a valid identifier char, so nothing is consumed.
      assertEquals("", identifier);
  }

  @Test(timeout = 4000)
  public void consumeCssIdentifier_replacesNullCharWithReplacementChar() throws Throwable {
      TokenQueue queue = new TokenQueue("b�L (");

      String identifier = queue.consumeCssIdentifier();

      // The embedded NULL (U+0000) is mapped to the REPLACEMENT CHARACTER (U+FFFD).
      assertEquals("b�L", identifier);
  }

  @Test(timeout = 4000)
  public void consumeCssIdentifier_throwsWhenQueueIsEmpty() throws Throwable {
      TokenQueue queue = new TokenQueue("722m6%0O=.8DAypB");
      // Drain the queue first (no terminators -> consumes everything).
      queue.consumeToAny(new String[0]);

      try {
        queue.consumeCssIdentifier();
        fail("Expecting exception: IllegalArgumentException");
      } catch(IllegalArgumentException e) {
         // CSS identifier expected, but end of input found
         verifyException("org.jsoup.parser.TokenQueue", e);
      }
  }

  // ---------------------------------------------------------------------------
  // chompBalanced(open, close): pulls a balanced run between two markers
  // ---------------------------------------------------------------------------

  @Test(timeout = 4000)
  public void chompBalanced_returnsContentBetweenMarkers() throws Throwable {
      TokenQueue queue = new TokenQueue("(1upvc8O");

      String content = queue.chompBalanced('(', 'v');

      // Content between the opening '(' and the closing 'v' marker.
      assertEquals("1up", content);
  }

  @Test(timeout = 4000)
  public void chompBalanced_quotedContentIsReturnedWhenNoMarkersPresent() throws Throwable {
      TokenQueue queue = new TokenQueue("'");

      // Opener ')' never appears; the quoted single char is returned as-is.
      String content = queue.chompBalanced(')', '$');
      assertEquals("'", content);

      // The queue is now exhausted, so a subsequent selector read differs.
      String selector = queue.consumeElementSelector();
      assertFalse(selector.equals((Object) content));
  }

  @Test(timeout = 4000)
  public void chompBalanced_throwsWhenCloserNeverFound() throws Throwable {
      TokenQueue queue = new TokenQueue("o`3'h7]LU\"nf[yzQ%n");

      try {
        queue.chompBalanced('o', 'o');
        fail("Expecting exception: IllegalArgumentException");
      } catch(IllegalArgumentException e) {
         // Did not find balanced marker at '`3'h7]LU\"nf[yzQ%n'
         verifyException("org.jsoup.helper.Validate", e);
      }
  }

  @Test(timeout = 4000)
  public void chompBalanced_throwsAfterPartialConsumptionWhenUnbalanced() throws Throwable {
      TokenQueue queue = new TokenQueue("_Tw\"FhC|($XN0!Uv;9");
      queue.consumeElementSelector(); // consumes leading "_Tw"

      try {
        queue.chompBalanced('"', '"');
        fail("Expecting exception: IllegalArgumentException");
      } catch(IllegalArgumentException e) {
         // Did not find balanced marker at 'FhC|($XN0!Uv;9'
         verifyException("org.jsoup.helper.Validate", e);
      }
  }

  @Test(timeout = 4000)
  public void chompBalanced_throwsWhenOnlyOpenerPresent() throws Throwable {
      TokenQueue queue = new TokenQueue("'");

      try {
        queue.chompBalanced('\'', '\'');
        fail("Expecting exception: IllegalArgumentException");
      } catch(IllegalArgumentException e) {
         // Did not find balanced marker at ''
         verifyException("org.jsoup.helper.Validate", e);
      }
  }

  @Test(timeout = 4000)
  public void chompBalanced_throwsWhenContentIsUnbalanced() throws Throwable {
      TokenQueue queue = new TokenQueue("Oy0ADe'8'-Re");

      try {
        queue.chompBalanced('O', 'O');
        fail("Expecting exception: IllegalArgumentException");
      } catch(IllegalArgumentException e) {
         // Did not find balanced marker at 'y0ADe'8'-Re'
         verifyException("org.jsoup.helper.Validate", e);
      }
  }

  @Test(timeout = 4000)
  public void chompBalanced_throwsAfterIdentifierConsumedWhenUnbalanced() throws Throwable {
      TokenQueue queue = new TokenQueue("8#cX#pxA*");
      queue.consumeCssIdentifier(); // consumes leading "8"

      try {
        queue.chompBalanced('#', 'p');
        fail("Expecting exception: IllegalArgumentException");
      } catch(IllegalArgumentException e) {
         // Did not find balanced marker at 'cX#pxA*'
         verifyException("org.jsoup.helper.Validate", e);
      }
  }

  // ---------------------------------------------------------------------------
  // escapeCssIdentifier(): static helper that escapes CSS special characters
  // ---------------------------------------------------------------------------

  @Test(timeout = 4000)
  public void escapeCssIdentifier_leavesNonAsciiCharUnescaped() throws Throwable {
      String escaped = TokenQueue.escapeCssIdentifier("");

      // Characters >= U+0080 are emitted verbatim.
      assertEquals("", escaped);
  }

  @Test(timeout = 4000)
  public void escapeCssIdentifier_escapesControlAndSpecialChars() throws Throwable {
      String escaped = TokenQueue.escapeCssIdentifier("p8moD0M0$t5mTH&");

      assertEquals("p8moD0M\\7f 0\\$t5mTH\\&", escaped);
  }

  @Test(timeout = 4000)
  public void escapeCssIdentifier_escapesLeadingDigitAsCodepoint() throws Throwable {
      String escaped = TokenQueue.escapeCssIdentifier("722m6%0O=.8DAypB");

      // A leading digit is escaped as a code point ("\37 "), plus the specials.
      assertEquals("\\37 22m6\\%0O\\=\\.8DAypB", escaped);
  }

  @Test(timeout = 4000)
  public void escapeCssIdentifier_handlesLeadingHyphenFollowedByLetter() throws Throwable {
      String escaped = TokenQueue.escapeCssIdentifier("-[-Tg0Y[E");

      assertEquals("-\\[-Tg0Y\\[E", escaped);
  }

  @Test(timeout = 4000)
  public void escapeCssIdentifier_escapesDigitAfterLeadingHyphen() throws Throwable {
      String escaped = TokenQueue.escapeCssIdentifier("-8Lc8X#GxA*");

      // "-8" -> hyphen kept, digit escaped as code point ("\38 ").
      assertEquals("-\\38 Lc8X\\#GxA\\*", escaped);
  }

  @Test(timeout = 4000)
  public void escapeCssIdentifier_escapesLoneHyphen() throws Throwable {
      String escaped = TokenQueue.escapeCssIdentifier("-");

      // A single "-" with no following char is escaped.
      assertEquals("\\-", escaped);
  }

  @Test(timeout = 4000)
  public void escapeCssIdentifier_emptyInputReturnsEmpty() throws Throwable {
      String escaped = TokenQueue.escapeCssIdentifier("");

      assertEquals("", escaped);
  }

  @Test(timeout = 4000)
  public void escapeCssIdentifier_escapesBackspaceControlChar() throws Throwable {
      String escaped = TokenQueue.escapeCssIdentifier("p\bmoD0M");

      // The backspace (U+0008) is escaped as a code point ("\8 ").
      assertEquals("p\\8 moD0M", escaped);
  }

  // ---------------------------------------------------------------------------
  // unescape(): static helper that removes backslash escapes
  // ---------------------------------------------------------------------------

  @Test(timeout = 4000)
  public void unescape_removesBackslashEscapes() throws Throwable {
      String unescaped = TokenQueue.unescape("[\\x00-\\x1f]*");

      // Each "\\" escape is dropped, leaving the following char.
      assertEquals("[x00-x1f]*", unescaped);
  }

  @Test(timeout = 4000)
  public void unescape_returnsInputUnchangedWhenNoBackslash() throws Throwable {
      String unescaped = TokenQueue.unescape(" 22m6%0O=.8DAypB");

      assertEquals(" 22m6%0O=.8DAypB", unescaped);
  }

  // ---------------------------------------------------------------------------
  // consumeWhitespace(): consumes a run of leading whitespace
  // ---------------------------------------------------------------------------

  @Test(timeout = 4000)
  public void consumeWhitespace_returnsTrueWhenWhitespaceConsumed() throws Throwable {
      TokenQueue queue = new TokenQueue("                  ");

      boolean consumedWhitespace = queue.consumeWhitespace();

      assertTrue(consumedWhitespace);
  }

  // ---------------------------------------------------------------------------
  // consumeToAny(...): consumes up to the first of any given terminators
  // ---------------------------------------------------------------------------

  @Test(timeout = 4000)
  public void consumeToAny_returnsEmptyWhenTerminatorMatchesAtStart() throws Throwable {
      TokenQueue queue = new TokenQueue("p h7u#");
      String[] terminators = new String[] { "p h7u#" };

      String consumed = queue.consumeToAny(terminators);

      // Terminator matches immediately, so nothing is consumed.
      assertEquals("", consumed);
  }

  @Test(timeout = 4000)
  public void consumeToAny_consumesRemainderWhenTerminatorNoLongerMatches() throws Throwable {
      TokenQueue queue = new TokenQueue("p h7u#");
      queue.advance(); // drop the leading 'p'
      String[] terminators = new String[] { "p h7u#" };

      String consumed = queue.consumeToAny(terminators);

      // After dropping 'p', the terminator no longer matches, so the rest is consumed.
      assertEquals(" h7u#", consumed);
  }

  // ---------------------------------------------------------------------------
  // consume(seq): consumes an expected sequence or throws
  // ---------------------------------------------------------------------------

  @Test(timeout = 4000)
  public void consume_throwsWhenSequenceDoesNotMatch() throws Throwable {
      TokenQueue queue = new TokenQueue("p");

      try {
        queue.consume("=H;zT#>e+|')Uz");
        fail("Expecting exception: IllegalStateException");
      } catch(IllegalStateException e) {
         // Queue did not match expected sequence
         verifyException("org.jsoup.parser.TokenQueue", e);
      }
  }

  @Test(timeout = 4000)
  public void consume_emptySequenceIsNoOp() throws Throwable {
      TokenQueue queue = new TokenQueue("\"x*2MP%xE'0OK&5i:j");

      // Consuming the empty string always matches and consumes nothing.
      queue.consume("");
  }

  // ---------------------------------------------------------------------------
  // matchChomp(...): match-and-consume helpers
  // ---------------------------------------------------------------------------

  @Test(timeout = 4000)
  public void matchChompChar_consumesAndReturnsTrueWhenCharMatches() throws Throwable {
      TokenQueue queue = new TokenQueue("722m6%0O=.8DAypB");

      boolean matched = queue.matchChomp('7');

      assertTrue(matched);
  }

  @Test(timeout = 4000)
  public void matchChompChar_returnsFalseWhenCharDoesNotMatch() throws Throwable {
      TokenQueue queue = new TokenQueue("'");

      boolean matched = queue.matchChomp('r');

      assertFalse(matched);
  }

  @Test(timeout = 4000)
  public void matchChompString_consumesAndReturnsTrueWhenSequenceMatches() throws Throwable {
      TokenQueue queue = new TokenQueue("'");

      boolean matched = queue.matchChomp("'");

      assertTrue(matched);
  }

  // ---------------------------------------------------------------------------
  // matches(...) / matchesAny(...): non-consuming lookahead
  // ---------------------------------------------------------------------------

  @Test(timeout = 4000)
  public void matchesString_emptySequenceMatchesEmptyQueue() throws Throwable {
      TokenQueue queue = new TokenQueue("");

      boolean matches = queue.matches("");

      assertTrue(matches);
  }

  @Test(timeout = 4000)
  public void matchesChar_returnsFalseOnEmptyQueue() throws Throwable {
      TokenQueue queue = new TokenQueue("");

      // U+007F (DEL) does not match an empty queue.
      boolean matches = queue.matches('');

      assertFalse(matches);
  }

  @Test(timeout = 4000)
  public void matchesAny_returnsFalseWhenNoCharMatches() throws Throwable {
      TokenQueue queue = new TokenQueue("'");
      char[] candidates = new char[4]; // all NUL chars

      boolean matchesAny = queue.matchesAny(candidates);

      assertFalse(matchesAny);
  }

  // ---------------------------------------------------------------------------
  // advance(): drops the next char (safe on empty queue)
  // ---------------------------------------------------------------------------

  @Test(timeout = 4000)
  public void advance_onEmptyQueueIsSafe() throws Throwable {
      TokenQueue queue = new TokenQueue("");

      queue.advance(); // no-op, must not throw
  }

  // ---------------------------------------------------------------------------
  // consumeTo / remainder / toString
  // ---------------------------------------------------------------------------

  @Test(timeout = 4000)
  public void consumeTo_consumesAllWhenSequenceNotFound() throws Throwable {
      TokenQueue queue = new TokenQueue("'");

      String consumed = queue.consumeTo("Object must not be null");

      // The terminator is absent, so the whole queue is consumed.
      assertEquals("'", consumed);
  }

  @Test(timeout = 4000)
  public void remainder_returnsEntireRemainingQueue() throws Throwable {
      TokenQueue queue = new TokenQueue("   ");

      String remaining = queue.remainder();

      assertEquals("   ", remaining);
  }

  @Test(timeout = 4000)
  public void toString_returnsRemainingQueueContents() throws Throwable {
      TokenQueue queue = new TokenQueue("'");

      String contents = queue.toString();

      assertEquals("'", contents);
  }
}
